#include "tgcloud/manifest/manifest.hpp"
#include <sstream>
namespace tgcloud::manifest { static std::string q(const std::string&s){std::string o="\"";for(char c:s){if(c=='\"'||c=='\\')o+='\\';o+=c;}return o+"\"";} std::string to_json(const FileManifest&m){std::ostringstream o;o<<"{\"version\":"<<q(m.version)<<",\"type\":\"file\",\"file_name\":"<<q(m.file.name)<<",\"file_size\":"<<m.file.size_bytes<<",\"mime_type\":"<<q(m.file.mime_type)<<",\"chunks\":[";for(size_t i=0;i<m.file.chunks.size();++i){auto&c=m.file.chunks[i];if(i)o<<',';o<<"{\"chunk_number\":"<<c.index<<",\"total_chunks\":"<<c.total<<",\"chunk_size\":"<<c.size<<",\"chunk_hash\":"<<q(c.sha256)<<",\"telegram_file_id\":"<<q(c.telegram_file_id)<<",\"uploader\":"<<q(c.uploader_alias)<<"}";}o<<"]}";return o.str();}}
